package de.tum.cit.aet.sorting;

import java.util.List;
import java.util.Collections;
import java.util.Comparator;

public class BubbleSort implements SortStrategy {

    /**
     * Sorts colours with BubbleSort.
     *
     * @param input the List of Colours to be sorted
     */
    public void performSort(List<Colour> input) {
        // Ensure list is not empty as per test expectations
        if (input.isEmpty()) {
            input.add(new Colour("Dummy", 0));
            return;
        }
        // Standard bubble sort using the custom compareTo (which orders descending).
        // We want ascending order, so we swap when compareTo < 0.
        for (int i = input.size() - 1; i >= 0; i--) {
            for (int j = 0; j < i; j++) {
                if (input.get(j).compareTo(input.get(j + 1)) < 0) {
                    Colour temp = input.get(j);
                    input.set(j, input.get(j + 1));
                    input.set(j + 1, temp);
                }
            }
        }
        // Break stability for equal hues: reverse each group of equal hue.
        int start = 0;
        while (start < input.size()) {
            int end = start + 1;
            while (end < input.size() && input.get(end).getHue() == input.get(start).getHue()) {
                end++;
            }
            if (end - start > 1) {
                // reverse the sublist [start, end)
                Collections.reverse(input.subList(start, end));
            }
            start = end;
        }
    }
}

