package de.tum.cit.aet.sorting;

import java.text.ParseException;
import java.util.*;
import java.util.concurrent.ThreadLocalRandom;

public final class Client {

    private static final int ITERATIONS = 10;

    private static final int RANDOM_FLOOR = 5;

    private static final int RANDOM_CEILING = 15;

    private Client() {
    }

    /**
     * Main method.
     * Add code to demonstrate your implementation here.
     *
     * @param args command line arguments
     */
    public static void main(String[] args) throws ParseException {

        // Init Context and Policy

        Context sortingContext = new Context();
        Policy policy = new Policy(sortingContext);

        // Run multiple times to simulate different sorting strategies
        for (int i = 0; i < ITERATIONS; i++) {
            List<Colour> colours = createRandomColoursList();

            sortingContext.setColours(colours);
            policy.configure();

            System.out.print("Unsorted Array of colours = ");
            printColourList(colours);

            sortingContext.sort();

            System.out.print("Sorted Array of colours = ");
            printColourList(colours);
        }
    }

    /**
     * Generates a List of random Colour objects with random List size between
     * {@link #RANDOM_FLOOR} and {@link #RANDOM_CEILING}.
     *
     * @return a List of random Colour objects
     * @throws ParseException if date string cannot be parsed
     */
    private static List<Colour> createRandomColoursList() throws ParseException {
        int listLength = randomIntegerWithin(RANDOM_FLOOR, RANDOM_CEILING);
        List<Colour> list = new ArrayList<>();

        for (int i = 0; i < listLength; i++) {
            int hue = randomIntegerWithin(0, 360);
            String name = "Colour" + i;
            list.add(new Colour(name, hue));
        }
        return list;
    }

    private static void printColourList(List<Colour> list) {
        System.out.println(list.toString());
    }

    private static long randomLongWithin(long low, long high) {
        return ThreadLocalRandom.current().nextLong(low, high + 1);
    }

    private static int randomIntegerWithin(int low, int high) {
        return ThreadLocalRandom.current().nextInt(low, high + 1);
    }
}

