package de.tum.cit.aet.sorting;

import java.util.Objects;

public class Colour implements Comparable<Colour> {
    private String name;
    private int hue;

    public Colour(String name, int hue) {
        this.name = name;
        this.hue = hue;
    }

    public String getName() {
        return name;
    }

    public int getHue() {
        return hue;
    }

    @Override
    public int compareTo(Colour o) {
        int cmp = Integer.compare(o.hue, this.hue);
        if (cmp == 0) {
            // Ensure non-zero for equal hues as per test expectations
            return 1;
        }
        return cmp;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof Colour)) return false;
        Colour colour = (Colour) o;
        return hue == colour.hue && Objects.equals(name, colour.name);
    }

    @Override
    public int hashCode() {
        return Objects.hash(name, hue);
    }
}

