package de.tum.cit.aet.sorting;

public class Policy {

    /**
     * @oracleIgnore
     */
    private static final int COLOURS_SIZE_THRESHOLD = 10;

    private Context context;

    public Policy(Context context) {
        this.context = context;
    }

    /**
     * Chooses a strategy depending on the number of colour objects.
     */
    public void configure() {
        if (this.context.getColours().size() > COLOURS_SIZE_THRESHOLD) {
            System.out.println("More than " + COLOURS_SIZE_THRESHOLD
                + " colours, choosing merge sort!");
            this.context.setSortAlgorithm(new MergeSort());
        } else {
            System.out.println("Less or equal than " + COLOURS_SIZE_THRESHOLD
                + " colours. choosing bubble sort!");
            this.context.setSortAlgorithm(new BubbleSort());
        }
    }
}

package de.tum.cit.aet.sorting;

import java.util.List;

public interface SortStrategy {

    /**
     * Sorts a list of Colours.
     *
     * @param input list of Colours
     */
    void performSort(List<Colour> input);
}
